def _count_by_brute_force(arr, k):
    """Count non-empty subsequences whose product is smaller than k.

    Used only for inputs outside the promised non-negative range, or
    containing values between zero and one, where products need not
    grow monotonically and the dynamic-programming count cannot prune.
    """
    count = 0
    for mask in range(1, 1 << len(arr)):
        product = 1
        for index, value in enumerate(arr):
            if mask & (1 << index):
                product *= value
        if product < k:
            count += 1
    return count


def _count_nonempty_rest(rest, k):
    """Count non-empty subsets of ``rest`` whose product is below k.

    Every value in ``rest`` is positive and different from one.
    """
    if not rest:
        return 0

    if any(value < 1 for value in rest):
        return _count_by_brute_force(rest, k)

    # All values exceed one, so every subset product is at most the
    # product of the whole list.  If that product is below k, all
    # non-empty subsets qualify.
    total_product = 1
    for value in rest:
        total_product *= value
        if total_product >= k:
            break
    else:
        return 2 ** len(rest) - 1

    # Dynamic programming over distinct products below k.  The entry
    # for product 1 initially represents the empty subset; it is
    # subtracted at the end so that only non-empty subsets are counted.
    counts = {1: 1}
    for value in rest:
        for existing_product, count in list(counts.items()):
            new_product = existing_product * value
            if new_product < k:
                counts[new_product] = counts.get(new_product, 0) + count
    return sum(counts.values()) - 1


def _count_nonempty_positive(values, k):
    """Count non-empty subsets of positive values with product below k."""
    if not values:
        return 0

    ones = sum(1 for value in values if value == 1)
    rest = [value for value in values if value != 1]
    rest_count = _count_nonempty_rest(rest, k)

    # A qualifying subset of ``rest`` may be combined with any subset
    # of the ones without changing its product.  Additionally, a
    # non-empty subset consisting only of ones has product 1.
    one_choices = 2 ** ones
    total = rest_count * one_choices
    if k > 1:
        total += one_choices - 1
    return total


def no_of_subsequences(arr, k):
    """Write a function to find the number of subsequences having product smaller than k for the given non negative array."""
    values = list(arr)

    if any(value < 0 for value in values):
        return _count_by_brute_force(values, k)

    if k <= 0 or not values:
        return 0

    zeros = sum(1 for value in values if value == 0)
    positives = [value for value in values if value > 0]
    positive_count = _count_nonempty_positive(positives, k)

    if zeros:
        # Any subsequence containing at least one zero has product 0,
        # which is below the (positive) k, regardless of which positive
        # elements accompany the zero(s).
        subsequences_with_zero = (2 ** zeros - 1) * 2 ** len(positives)
        return subsequences_with_zero + positive_count

    return positive_count
